using System;using System.IO;using System.Linq;using System.Text;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class FinalCitySignsAudit{
static FinalCitySignsAudit(){EditorApplication.update+=Poll;}static void Poll(){if(!File.Exists("FinalCitySignsAudit.request")||EditorApplication.isCompiling)return;File.Delete("FinalCitySignsAudit.request");var s=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var all=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshRenderer>(true)).Where(r=>r.enabled&&r.gameObject.activeInHierarchy&&r.sharedMaterials.Any(m=>m&&m.name.StartsWith("Building"))).ToArray();var log=new StringBuilder();log.AppendLine("building renderers="+all.Length);foreach(var r in all.OrderByDescending(r=>r.bounds.size.y).Take(35))log.AppendLine(r.name+" bounds="+r.bounds+" material="+string.Join("|",r.sharedMaterials.Select(m=>m?m.name:"null"))+" prefab="+PrefabUtility.GetPrefabAssetPathOfNearestInstanceRoot(r.gameObject));foreach(var root in s.GetRootGameObjects())log.AppendLine("ROOT "+root.name+" prefab="+PrefabUtility.GetPrefabAssetPathOfNearestInstanceRoot(root));File.WriteAllText("FinalEnvironmentRoadReview/CitySignsAudit.txt",log.ToString());}}
